window.QBANK = window.QBANK || {};
window.QBANK["kuliah-inggris"] = {
  level: "Kuliah",
  subject: "Bahasa Inggris Akademik",
  duration: 900,
  questions: [
    { q: "She ___ to school every day.", options: ["go", "goes", "going", "gone"], answer: 1, solution: "1. Subjeknya she (orang ketiga tunggal) dan waktunya every day (kebiasaan). 2. Simple present untuk orang ketiga tunggal memakai kata kerja + s/es. 3. Jadi jawabannya goes." },
    { q: "The report ___ by the committee yesterday.", options: ["is written", "was written", "writes", "has written"], answer: 1, solution: "1. Subjek the report adalah benda yang menerima aksi (ditulis), jadi kalimat pasif. 2. Waktunya yesterday, maka past tense: was/were + past participle. 3. Jadi jawabannya was written." },
    { q: "If I ___ rich, I would travel the world.", options: ["am", "were", "will be", "have been"], answer: 1, solution: "1. Ini conditional type 2: pengandaian yang tidak nyata saat ini. 2. Polanya: If + past tense, would + verb. Untuk semua subjek dipakai were. 3. Jadi jawabannya were." },
    { q: "The word UBICUITOUS is closest in meaning to ...", options: ["rare", "present everywhere", "expensive", "ancient"], answer: 1, solution: "1. Ubiquitous berasal dari kata Latin ubique yang berarti everywhere. 2. Artinya hadir di mana-mana, misalnya smartphones are ubiquitous. 3. Jadi jawabannya present everywhere." },
    { q: "They have ___ in Jakarta since 2010.", options: ["live", "lived", "living", "lives"], answer: 1, solution: "1. Ada have dan since 2010, tanda present perfect. 2. Polanya: have/has + past participle (verb 3). 3. Bentuk verb 3 dari live adalah lived." },
    { q: "The teacher suggested that he ___ harder.", options: ["studies", "study", "studied", "studying"], answer: 1, solution: "1. Kata suggest termasuk subjunctive: suggest that + subject + bare infinitive. 2. Bentuk dasar tanpa to dan tanpa s dipakai untuk semua subjek. 3. Jadi jawabannya study." },
    { q: "Neither of the answers ___ correct.", options: ["is", "are", "were", "be"], answer: 0, solution: "1. Neither berarti tidak satu pun, selalu dianggap tunggal. 2. Kata kerja untuk subjek tunggal adalah is. 3. Jadi jawabannya is." },
    { q: "Read the passage: Photosynthesis is the process by which green plants convert sunlight, water, and carbon dioxide into food and oxygen. This process mainly occurs in the leaves, where chlorophyll captures light energy. What is the main idea of the passage?", options: ["How plants make food through photosynthesis", "The parts of a leaf", "Why water is important for humans", "The history of botany"], answer: 0, solution: "1. Kalimat pertama menjelaskan definisi fotosintesis secara keseluruhan. 2. Kalimat kedua hanya detail pendukung tentang daun. 3. Ide pokoknya adalah how plants make food through photosynthesis." },
    { q: "By the time we arrived, the movie ___.", options: ["started", "had started", "has started", "starts"], answer: 1, solution: "1. Ada dua kejadian lampau: film mulai DULU, kami tiba KEMUDIAN. 2. Kejadian yang lebih dulu memakai past perfect: had + past participle. 3. Jadi jawabannya had started." },
    { q: "The word BENEVOLENT is closest in meaning to ...", options: ["cruel", "kind and generous", "wealthy", "famous"], answer: 1, solution: "1. Benevolent berasal dari bene (baik) + volent (berkehendak). 2. Artinya baik hati dan murah hati. 3. Jadi jawabannya kind and generous." },
    { q: "She is the ___ student in the class.", options: ["more intelligent", "most intelligent", "intelligentest", "more intelligentest"], answer: 1, solution: "1. Ada the dan in the class, tanda superlative (paling). 2. Kata sifat panjang (3 suku kata) memakai most + adjective. 3. Jadi jawabannya most intelligent." },
    { q: "If you had studied, you ___ passed the exam.", options: ["would have", "will have", "would", "have"], answer: 0, solution: "1. Ini conditional type 3: penyesalan tentang masa lalu. 2. Polanya: If + past perfect, would have + past participle. 3. Jadi jawabannya would have." },
    { q: "The cake was ___ by my mother.", options: ["bake", "baked", "baking", "bakes"], answer: 1, solution: "1. Ada was, tanda kalimat pasif past tense. 2. Pola pasif: was/were + past participle (verb 3). 3. Bentuk verb 3 dari bake adalah baked." },
    { q: "He denied ___ the money.", options: ["to take", "taking", "take", "taken"], answer: 1, solution: "1. Kata deny termasuk verb yang diikuti gerund (verb-ing). 2. Deny tidak bisa diikuti to-infinitive. 3. Jadi jawabannya taking." },
    { q: "The word AMBIGUOUS is closest in meaning to ...", options: ["clear", "having more than one meaning", "bright", "loud"], answer: 1, solution: "1. Ambiguous berasal dari ambi (dua) + agere (menggerakkan). 2. Artinya bisa ditafsirkan lebih dari satu cara. 3. Jadi jawabannya having more than one meaning." },
    { q: "There ___ a lot of traffic today.", options: ["is", "are", "were", "be"], answer: 0, solution: "1. Subjek sebenarnya adalah a lot of traffic (lalu lintas, tunggal tak terhitung). 2. Waktunya today (sekarang), jadi pakai is. 3. Jadi jawabannya is." },
    { q: "I wish I ___ taller.", options: ["am", "were", "will be", "have been"], answer: 1, solution: "1. Wish untuk pengandaian saat ini memakai past tense. 2. Untuk semua subjek, termasuk I, dipakai were dalam pengandaian. 3. Jadi jawabannya were." },
    { q: "The students ___ English for three years.", options: ["study", "have studied", "are studying", "will study"], answer: 1, solution: "1. Ada for three years, tanda present perfect (mulai dulu sampai sekarang). 2. Subjek jamak the students memakai have + past participle. 3. Jadi jawabannya have studied." },
    { q: "Read the passage: Artificial intelligence is increasingly used in healthcare, from diagnosing diseases to predicting outbreaks. However, experts warn that AI should support doctors, not replace them. According to the passage, experts believe AI should ...", options: ["replace doctors completely", "assist doctors rather than replace them", "work without any supervision", "stop being developed"], answer: 1, solution: "1. Kata kuncinya ada di kalimat kedua: AI should support doctors, not replace them. 2. Support artinya membantu atau mendampingi. 3. Jadi jawabannya assist doctors rather than replace them." },
    { q: "___ the bad weather, the match continued.", options: ["Despite", "Although", "Because", "Since"], answer: 0, solution: "1. Setelah titik-titik langsung diikuti frasa benda the bad weather, bukan klausa. 2. Despite diikuti kata benda, sedangkan although diikuti klausa (subjek + kata kerja). 3. Jadi jawabannya Despite." },
    { q: "The word METICULOUS is closest in meaning to ...", options: ["careless", "very careful and precise", "quick", "lazy"], answer: 1, solution: "1. Meticulous menggambarkan orang yang sangat teliti terhadap detail. 2. Lawan katanya adalah careless (ceroboh). 3. Jadi jawabannya very careful and precise." },
    { q: "She asked me where ___.", options: ["I lived", "did I live", "I live", "do I live"], answer: 0, solution: "1. Ini reported speech (kalimat tidak langsung), jadi tidak pakai inversi tanya. 2. Urutannya tetap subjek + kata kerja: I lived. 3. Jadi jawabannya I lived." },
    { q: "Hardly ___ when the phone rang.", options: ["I had slept", "had I slept", "I have slept", "did I sleep"], answer: 1, solution: "1. Hardly di awal kalimat memicu inversi (kata kerja bantu pindah ke depan subjek). 2. Kejadiannya lampau dan berurutan, jadi past perfect: had + subjek + past participle. 3. Jadi jawabannya had I slept." },
    { q: "The Eiffel Tower ___ in 1889.", options: ["built", "was built", "is built", "has built"], answer: 1, solution: "1. Menara adalah benda yang DIBANGUN (menerima aksi), jadi pasif. 2. Tahun 1889 adalah masa lampau: was/were + past participle. 3. Jadi jawabannya was built." },
    { q: "The word RELUCTANT is closest in meaning to ...", options: ["willing", "unwilling", "excited", "ready"], answer: 1, solution: "1. Reluctant menggambarkan keengganan melakukan sesuatu. 2. Lawan katanya adalah willing (bersedia). 3. Jadi jawabannya unwilling." },
    { q: "Each of the students ___ a laptop.", options: ["have", "has", "are having", "having"], answer: 1, solution: "1. Kata each selalu dianggap tunggal walau diikuti frasa jamak. 2. Kata kerja untuk subjek tunggal adalah has. 3. Jadi jawabannya has." },
    { q: "If it rains tomorrow, we ___ at home.", options: ["would stay", "will stay", "stayed", "stays"], answer: 1, solution: "1. Ini conditional type 1: kemungkinan nyata di masa depan. 2. Polanya: If + present, will + verb. 3. Jadi jawabannya will stay." },
    { q: "The book, ___ cover is red, is mine.", options: ["which", "whose", "who", "whom"], answer: 1, solution: "1. Kata ganti harus menunjukkan kepemilikan (cover milik the book). 2. Untuk benda maupun orang, kata ganti milik adalah whose. 3. Jadi jawabannya whose." },
    { q: "Read the passage: Borobudur, located in Central Java, is the largest Buddhist temple in the world. Built in the 9th century, it attracts millions of visitors every year. Which statement is TRUE according to the passage?", options: ["Borobudur is the largest Buddhist temple in the world", "Borobudur is located in East Java", "Borobudur was built in the 19th century", "Borobudur attracts only local visitors"], answer: 0, solution: "1. Teks menyebut located in Central Java, bukan East Java. 2. Teks menyebut built in the 9th century, bukan 19th. 3. Pernyataan yang sesuai teks adalah Borobudur is the largest Buddhist temple in the world." },
    { q: "He is accustomed ___ early.", options: ["to wake", "to waking", "waking", "wake"], answer: 1, solution: "1. Frasa accustomed to selalu diikuti gerund (verb-ing), bukan infinitive. 2. To di sini adalah preposisi, bukan bagian dari to-infinitive. 3. Jadi jawabannya to waking." },
    { q: "The word CONTROVERSIAL is closest in meaning to ...", options: ["boring", "causing public disagreement", "peaceful", "simple"], answer: 1, solution: "1. Controversial berasal dari controversy (perdebatan publik). 2. Artinya menimbulkan pro dan kontra di masyarakat. 3. Jadi jawabannya causing public disagreement." },
    { q: "Not only ___ late, but he also forgot his homework.", options: ["he came", "did he come", "he comes", "does he come"], answer: 1, solution: "1. Not only di awal kalimat memicu inversi seperti hardly. 2. Kejadiannya lampau: did + subjek + verb dasar. 3. Jadi jawabannya did he come." },
    { q: "The meeting ___ until next week.", options: ["postponed", "was postponed", "has been postponed", "postpones"], answer: 2, solution: "1. Rapat adalah yang DITUNDA (menerima aksi), jadi pasif. 2. Until next week menunjukkan hasil yang masih berlaku sekarang: present perfect passive. 3. Jadi jawabannya has been postponed." },
    { q: "She speaks English ___.", options: ["fluent", "fluently", "fluency", "fluentest"], answer: 1, solution: "1. Kata yang menerangkan kata kerja speaks harus berupa adverb. 2. Adverb dibentuk dari adjective + ly. 3. Jadi jawabannya fluently." },
    { q: "The word INEVITABLE is closest in meaning to ...", options: ["avoidable", "unavoidable", "unlikely", "impossible"], answer: 1, solution: "1. Inevitable berasal dari in (tidak) + evitable (dapat dihindari). 2. Artinya pasti terjadi dan tidak bisa dihindari. 3. Jadi jawabannya unavoidable." },
    { q: "I look forward ___ you soon.", options: ["to see", "to seeing", "seeing", "see"], answer: 1, solution: "1. Frasa look forward to selalu diikuti gerund. 2. To di sini preposisi, bukan to-infinitive. 3. Jadi jawabannya to seeing." },
    { q: "The doctor told him to give ___ smoking.", options: ["up", "off", "in", "away"], answer: 0, solution: "1. Give up adalah phrasal verb yang berarti berhenti dari kebiasaan. 2. Give off berarti mengeluarkan, give in berarti menyerah. 3. Konteks berhenti merokok: jawabannya up." },
    { q: "Read the passage: The coastal city is vulnerable to flooding because it lies below sea level. The word VULNERABLE is closest in meaning to ...", options: ["easily harmed", "well protected", "far away", "very rich"], answer: 0, solution: "1. Konteksnya kota di bawah permukaan laut menghadapi banjir. 2. Vulnerable berarti mudah terkena bahaya atau damage. 3. Jadi jawabannya easily harmed." },
    { q: "Scarcely had she arrived ___ it started raining.", options: ["when", "than", "then", "that"], answer: 0, solution: "1. Pasangan tetap dari scarcely/hardly adalah when. 2. Than pasangannya rather, then menunjukkan urutan waktu biasa. 3. Jadi jawabannya when." },
    { q: "The person to ___ I spoke is my teacher.", options: ["who", "whom", "which", "whose"], answer: 1, solution: "1. Kata ganti mengikuti preposisi to dan merujuk pada orang sebagai objek. 2. Bentuk objek formal untuk orang adalah whom. 3. Jadi jawabannya whom." },
    { q: "The word DETERIORATE is closest in meaning to ...", options: ["improve", "become worse", "stay the same", "disappear"], answer: 1, solution: "1. Deteriorate menggambarkan kondisi yang menurun. 2. Lawan katanya adalah improve (membaik). 3. Jadi jawabannya become worse." },
    { q: "Had I known, I ___ come earlier.", options: ["would have", "will", "would", "have"], answer: 0, solution: "1. Ini inversi dari conditional type 3 (If I had known). 2. Pola type 3: would have + past participle. 3. Jadi jawabannya would have." },
    { q: "She has been working here ___ 2019.", options: ["since", "for", "from", "at"], answer: 0, solution: "1. Present perfect continuous dengan titik awal waktu tertentu. 2. Since dipakai untuk titik waktu (2019), for untuk durasi. 3. Jadi jawabannya since." },
    { q: "The results were ___ than expected.", options: ["good", "better", "best", "well"], answer: 1, solution: "1. Ada than, tanda comparative (perbandingan). 2. Bentuk comparative dari good adalah better (irregular). 3. Jadi jawabannya better." },
    { q: "Read the passage: The internet has transformed how people communicate, learn, and do business. Yet the digital divide means millions still lack reliable access. What is the main idea of the passage?", options: ["The internet is harmful", "The internet brings benefits but access remains unequal", "Everyone now has internet access", "Business is the only benefit of the internet"], answer: 1, solution: "1. Kalimat pertama menyebut manfaat besar internet. 2. Kata yet menandakan kontras: jutaan orang belum punya akses. 3. Ide pokoknya: manfaat besar tapi akses belum merata." },
    { q: "___ you ever been to Bali?", options: ["Have", "Has", "Did", "Do"], answer: 0, solution: "1. Ada ever dan pengalaman hidup sampai sekarang: present perfect. 2. Subjek you memakai have. 3. Jadi jawabannya Have." },
    { q: "The word PRAGMATIC is closest in meaning to ...", options: ["idealistic", "practical", "theoretical", "emotional"], answer: 1, solution: "1. Pragmatic menggambarkan pendekatan yang mengutamakan hasil nyata. 2. Lawan katanya adalah idealistic. 3. Jadi jawabannya practical." },
    { q: "It is important that she ___ on time.", options: ["is", "be", "was", "will be"], answer: 1, solution: "1. Pola it is important that termasuk subjunctive. 2. Setelah that dipakai bare infinitive untuk semua subjek. 3. Jadi jawabannya be." },
    { q: "The thief was caught ___ the police.", options: ["by", "with", "from", "of"], answer: 0, solution: "1. Kalimat pasif yang menyebut pelaku aksi. 2. Pelaku dalam kalimat pasif diperkenalkan dengan by. 3. Jadi jawabannya by." },
    { q: "___ studying hard, he failed the exam.", options: ["Despite", "Although", "Because", "Unless"], answer: 0, solution: "1. Setelah titik-titik langsung diikuti gerund studying, bukan klausa. 2. Despite diikuti kata benda atau gerund; although butuh klausa lengkap. 3. Jadi jawabannya Despite." },
    { q: "She has been learning English ___ five years.", options: ["for", "from", "at", "since"], answer: 0, solution: "1. Kalimatnya present perfect continuous (has been learning) dengan durasi waktu. 2. For dipakai untuk durasi (five years), since untuk titik waktu. 3. Jadi jawabannya for." },
    { q: "By next year, the company ___ the new factory.", options: ["has completed", "will have completed", "will complete", "will be completing"], answer: 1, solution: "1. Ada by next year, tanda kejadian selesai sebelum waktu tertentu di masa depan. 2. Itu future perfect: will have + past participle. 3. Jadi jawabannya will have completed." },
    { q: "I ___ breakfast when the phone rang.", options: ["will have", "had", "was having", "have"], answer: 2, solution: "1. Kejadian yang sedang berlangsung (sarapan) diinterupsi kejadian lampau (telepon berdering). 2. Kejadian yang sedang berlangsung memakai past continuous: was/were + verb-ing. 3. Jadi jawabannya was having." },
    { q: "He ___ for ten hours before he finally rested.", options: ["has been working", "was working", "had worked", "had been working"], answer: 3, solution: "1. Dua kejadian lampau: bekerja dulu (durasi panjang), istirahat kemudian. 2. Kejadian berdurasi yang lebih dulu memakai past perfect continuous: had been + verb-ing. 3. Jadi jawabannya had been working." },
    { q: "They ___ the new policy since January.", options: ["have implemented", "are implementing", "had implemented", "implemented"], answer: 0, solution: "1. Ada since January, tanda mulai dulu dan masih berlaku. 2. Present perfect: have/has + past participle; subjek jamak pakai have. 3. Jadi jawabannya have implemented." },
    { q: "By 2030, scientists ___ a cure for the disease.", options: ["will discover", "will have discovered", "have discovered", "discover"], answer: 1, solution: "1. By 2030 menandakan selesai sebelum titik waktu di masa depan. 2. Future perfect: will have + past participle. 3. Jadi jawabannya will have discovered." },
    { q: "She ___ for the exam all night; she looks exhausted.", options: ["will study", "studied", "has been studying", "studies"], answer: 2, solution: "1. Ada all night dan akibat yang terlihat sekarang (exhausted). 2. Present perfect continuous untuk aktivitas berdurasi yang hasilnya terasa kini: has been + verb-ing. 3. Jadi jawabannya has been studying." },
    { q: "When I arrived, they ___ already.", options: ["have left", "were leaving", "left", "had left"], answer: 3, solution: "1. Dua kejadian lampau: mereka pergi DULU, saya tiba KEMUDIAN. 2. Kejadian yang lebih dulu memakai past perfect: had + past participle. 3. Jadi jawabannya had left." },
    { q: "The company ___ a new product this morning.", options: ["has announced", "had announced", "announces", "announced"], answer: 0, solution: "1. This morning masih bagian dari hari ini dan hasilnya relevan sekarang. 2. Present perfect: has + past participle untuk subjek tunggal. 3. Jadi jawabannya has announced." },
    { q: "He ___ in this city for a decade before moving abroad.", options: ["lived", "had lived", "has lived", "lives"], answer: 1, solution: "1. Tinggal di kota terjadi DULU sebelum pindah (keduanya lampau). 2. Kejadian yang lebih dulu memakai past perfect: had + past participle. 3. Jadi jawabannya had lived." },
    { q: "Next month, they ___ married for twenty years.", options: ["are", "will be", "will have been", "have been"], answer: 2, solution: "1. Next month dengan durasi twenty years menandakan durasi yang selesai di masa depan. 2. Future perfect continuous: will have been + durasi. 3. Jadi jawabannya will have been." },
    { q: "She ___ snow before she visited Canada.", options: ["has never seen", "never sees", "never saw", "had never seen"], answer: 3, solution: "1. Belum pernah melihat salju terjadi SEBELUM kunjungan (keduanya lampau). 2. Kejadian yang lebih dulu memakai past perfect: had + past participle. 3. Jadi jawabannya had never seen." },
    { q: "The train ___ when we reached the station.", options: ["had already departed", "has already departed", "departs", "already departed"], answer: 0, solution: "1. Kereta berangkat DULU, kami tiba KEMUDIAN (keduanya lampau). 2. Kejadian yang lebih dulu memakai past perfect. 3. Jadi jawabannya had already departed." },
    { q: "I ___ here since nine o'clock.", options: ["am waiting", "have been waiting", "waited", "wait"], answer: 1, solution: "1. Ada since nine o'clock, aktivitas masih berlangsung sampai sekarang. 2. Present perfect continuous: have been + verb-ing. 3. Jadi jawabannya have been waiting." },
    { q: "By the time you read this letter, I ___ the country.", options: ["am leaving", "will leave", "will have left", "left"], answer: 2, solution: "1. By the time menandakan selesai sebelum kejadian lain di masa depan. 2. Future perfect: will have + past participle. 3. Jadi jawabannya will have left." },
    { q: "They ___ the bridge for two years now.", options: ["are building", "had built", "built", "have been building"], answer: 3, solution: "1. Ada for two years dan now, aktivitas masih berlangsung. 2. Present perfect continuous: have been + verb-ing. 3. Jadi jawabannya have been building." },
    { q: "She ___ her assignment already.", options: ["has already finished", "had already finished", "finishes", "already finished"], answer: 0, solution: "1. Already dengan hasil yang relevan sekarang menandakan present perfect. 2. Subjek tunggal she memakai has + past participle. 3. Jadi jawabannya has already finished." },
    { q: "He ___ when the earthquake struck.", options: ["slept", "was sleeping", "had slept", "sleeps"], answer: 1, solution: "1. Tidur sedang berlangsung saat gempa terjadi (interupsi). 2. Kejadian yang sedang berlangsung memakai past continuous. 3. Jadi jawabannya was sleeping." },
    { q: "The scientists ___ the virus for months before the vaccine was approved.", options: ["were researching", "researched", "had been researching", "have researched"], answer: 2, solution: "1. Penelitian berdurasi terjadi SEBELUM persetujuan vaksin (keduanya lampau). 2. Kejadian berdurasi yang lebih dulu memakai past perfect continuous. 3. Jadi jawabannya had been researching." },
    { q: "I have ___ to Japan.", options: ["never went", "never go", "never gone", "never been"], answer: 3, solution: "1. Ada have, tanda present perfect untuk pengalaman hidup. 2. Been dipakai untuk pengalaman pernah ke suatu tempat, bukan gone. 3. Jadi jawabannya never been." },
    { q: "She ___ piano since she was six years old.", options: ["has been learning", "learns", "had learned", "learned"], answer: 0, solution: "1. Ada since she was six, aktivitas masih berlangsung sampai sekarang. 2. Present perfect continuous: has been + verb-ing. 3. Jadi jawabannya has been learning." },
    { q: "They ___ in London for five years before they returned home.", options: ["lived", "had lived", "have lived", "live"], answer: 1, solution: "1. Tinggal di London terjadi SEBELUM pulang (keduanya lampau). 2. Kejadian yang lebih dulu memakai past perfect. 3. Jadi jawabannya had lived." },
    { q: "The meeting ___ just now.", options: ["ends", "just ended", "has just ended", "had just ended"], answer: 2, solution: "1. Just now dengan hasil relevan kini menandakan present perfect. 2. Subjek tunggal memakai has + past participle. 3. Jadi jawabannya has just ended." },
    { q: "While she ___, he set the table.", options: ["had cooked", "cooks", "cooked", "was cooking"], answer: 3, solution: "1. While menandakan dua kejadian lampau yang berlangsung bersamaan. 2. Kejadian berdurasi memakai past continuous: was + verb-ing. 3. Jadi jawabannya was cooking." },
    { q: "I ___ a conference in Singapore next week.", options: ["will be attending", "attend", "have attended", "will attend"], answer: 0, solution: "1. Next week menandakan kejadian yang sedang berlangsung di masa depan. 2. Future continuous: will be + verb-ing. 3. Jadi jawabannya will be attending." },
    { q: "He ___ unwell lately.", options: ["felt", "has been feeling", "feels", "had felt"], answer: 1, solution: "1. Lately menandakan kondisi yang berlangsung sampai sekarang. 2. Present perfect continuous: has been + verb-ing. 3. Jadi jawabannya has been feeling." },
    { q: "By the time the rescue team arrived, the hikers ___ for three days.", options: ["are stranded", "were stranded", "had been stranded", "have been stranded"], answer: 2, solution: "1. Terdampar berdurasi terjadi SEBELUM tim tiba (keduanya lampau). 2. Kejadian berdurasi yang lebih dulu memakai past perfect continuous. 3. Jadi jawabannya had been stranded." },
    { q: "She ___ abroad for many years, so her English is fluent.", options: ["lives", "had lived", "lived", "has lived"], answer: 3, solution: "1. Tinggal di luar negeri sampai sekarang dan hasilnya terasa kini. 2. Present perfect: has + past participle. 3. Jadi jawabannya has lived." },
    { q: "The workers ___ since morning when the tunnel collapsed.", options: ["had been digging", "have dug", "dig", "dug"], answer: 0, solution: "1. Menggali berdurasi terjadi SEBELUM terowongan runtuh (keduanya lampau). 2. Kejadian berdurasi yang lebih dulu memakai past perfect continuous. 3. Jadi jawabannya had been digging." },
    { q: "We ___ for six hours by the time the exam starts.", options: ["study", "will have been studying", "have studied", "studied"], answer: 1, solution: "1. By the time the exam starts menandakan durasi selesai di masa depan. 2. Future perfect continuous: will have been + verb-ing. 3. Jadi jawabannya will have been studying." },
    { q: "By next Friday, I ___ this novel.", options: ["finished", "finish", "will have finished", "have finished"], answer: 2, solution: "1. By next Friday menandakan selesai sebelum waktu di masa depan. 2. Future perfect: will have + past participle. 3. Jadi jawabannya will have finished." },
    { q: "The children ___ outside when it started to rain.", options: ["had played", "play", "played", "were playing"], answer: 3, solution: "1. Bermain sedang berlangsung saat hujan mulai turun (interupsi). 2. Kejadian yang sedang berlangsung memakai past continuous. 3. Jadi jawabannya were playing." },
    { q: "He ___ his homework before dinner yesterday.", options: ["had finished", "has finished", "finishes", "finished"], answer: 0, solution: "1. Menyelesaikan PR terjadi SEBELUM makan malam (keduanya lampau). 2. Kejadian yang lebih dulu memakai past perfect. 3. Jadi jawabannya had finished." },
    { q: "We ___ each other since childhood.", options: ["know", "have known", "knew", "are knowing"], answer: 1, solution: "1. Ada since childhood, hubungan masih berlangsung sampai sekarang. 2. Present perfect untuk keadaan yang berlanjut: have + past participle. 3. Jadi jawabannya have known." },
    { q: "She will ___ here for ten years by December.", options: ["works", "work", "will have been working", "has worked"], answer: 2, solution: "1. By December dengan durasi ten years menandakan durasi selesai di masa depan. 2. Future perfect continuous: will have been + verb-ing. 3. Jadi jawabannya will have been working." },
    { q: "The new law ___ next month.", options: ["is enforced", "enforced", "will enforce", "will be enforced"], answer: 3, solution: "1. Undang-undang adalah yang DIBERLAKUKAN (menerima aksi), jadi pasif. 2. Next month adalah masa depan: will be + past participle. 3. Jadi jawabannya will be enforced." },
    { q: "The bridge ___ right now.", options: ["is being repaired", "repairs", "has repaired", "is repaired"], answer: 0, solution: "1. Jembatan adalah yang DIPERBAIKI, jadi pasif. 2. Right now sedang berlangsung: is being + past participle. 3. Jadi jawabannya is being repaired." },
    { q: "The suspect ___ when the lawyer arrived.", options: ["was questioned", "was being questioned", "is questioned", "questioned"], answer: 1, solution: "1. Tersangka adalah yang DIINTEROGASI, jadi pasif. 2. Sedang berlangsung saat pengacara tiba: past continuous passive. 3. Jadi jawabannya was being questioned." },
    { q: "The results ___ already.", options: ["were published", "published", "have been published", "are published"], answer: 2, solution: "1. Hasil adalah yang DIPUBLIKASIKAN, jadi pasif. 2. Already dengan hasil relevan kini: present perfect passive. 3. Jadi jawabannya have been published." },
    { q: "The documents ___ before the meeting started.", options: ["have been signed", "were signed", "signed", "had been signed"], answer: 3, solution: "1. Dokumen adalah yang DITANDATANGANI, jadi pasif. 2. Terjadi SEBELUM rapat dimulai (keduanya lampau): past perfect passive. 3. Jadi jawabannya had been signed." },
    { q: "The stadium ___ by 2027.", options: ["will have been completed", "will be completed", "has been completed", "will complete"], answer: 0, solution: "1. Stadion adalah yang DISELESAIKAN, jadi pasif. 2. By 2027 menandakan selesai sebelum waktu di masa depan: future perfect passive. 3. Jadi jawabannya will have been completed." },
    { q: "English ___ in many countries.", options: ["speaks", "is spoken", "spoke", "has spoken"], answer: 1, solution: "1. Bahasa Inggris adalah yang DITUTURKAN, jadi pasif. 2. Fakta umum memakai simple present passive: is + past participle. 3. Jadi jawabannya is spoken." },
    { q: "The thief ___ last night.", options: ["has arrested", "arrested", "was arrested", "is arrested"], answer: 2, solution: "1. Pencuri adalah yang DITANGKAP, jadi pasif. 2. Last night lampau: was + past participle. 3. Jadi jawabannya was arrested." },
    { q: "The room ___ every day.", options: ["cleaned", "has cleaned", "cleans", "is cleaned"], answer: 3, solution: "1. Kamar adalah yang DIBERSIHKAN, jadi pasif. 2. Every day menandakan kebiasaan: simple present passive. 3. Jadi jawabannya is cleaned." },
    { q: "The proposal ___ by the board.", options: ["was rejected", "is rejected", "has rejected", "rejected"], answer: 0, solution: "1. Proposal adalah yang DITOLAK, jadi pasif. 2. Konteks lampau: was + past participle. 3. Jadi jawabannya was rejected." },
    { q: "The project ___ in June.", options: ["will launch", "will be launched", "launches", "is launched"], answer: 1, solution: "1. Proyek adalah yang DILUNCURKAN, jadi pasif. 2. In June (mendatang) adalah masa depan: will be + past participle. 3. Jadi jawabannya will be launched." },
    { q: "The windows ___ by the storm.", options: ["were broken", "broke", "have been broken", "are broken"], answer: 2, solution: "1. Jendela adalah yang DIPECAHKAN, jadi pasif. 2. Hasil badai masih relevan kini: present perfect passive. 3. Jadi jawabannya have been broken." },
    { q: "The road ___ at the moment.", options: ["widens", "was widened", "is widened", "is being widened"], answer: 3, solution: "1. Jalan adalah yang DILEBARKAN, jadi pasif. 2. At the moment sedang berlangsung: is being + past participle. 3. Jadi jawabannya is being widened." },
    { q: "The manuscript ___ when the fire broke out.", options: ["was being edited", "is edited", "had edited", "was edited"], answer: 0, solution: "1. Naskah adalah yang DISUNTING, jadi pasif. 2. Sedang berlangsung saat kebakaran terjadi: past continuous passive. 3. Jadi jawabannya was being edited." },
    { q: "The vaccine ___ before it was released.", options: ["tested", "had been tested", "has been tested", "was tested"], answer: 1, solution: "1. Vaksin adalah yang DIUJI, jadi pasif. 2. Pengujian terjadi SEBELUM dirilis (keduanya lampau): past perfect passive. 3. Jadi jawabannya had been tested." },
    { q: "The invitation ___ to all members yesterday.", options: ["has sent", "sent", "was sent", "is sent"], answer: 2, solution: "1. Undangan adalah yang DIKIRIM (menerima aksi), jadi pasif. 2. Waktunya yesterday: was/were + past participle. 3. Jadi jawabannya was sent." },
    { q: "The old building ___ next month.", options: ["demolishes", "is demolished", "will demolish", "will be demolished"], answer: 3, solution: "1. Gedung adalah yang DIROBOHKAN (menerima aksi). 2. Next month adalah masa depan: will be + past participle. 3. Jadi jawabannya will be demolished." },
    { q: "The homework ___ by Friday.", options: ["must be submitted", "submits", "is submitted", "must submit"], answer: 0, solution: "1. PR adalah yang DIKUMPULKAN, jadi pasif. 2. Modal passive: must be + past participle. 3. Jadi jawabannya must be submitted." },
    { q: "The rules ___ by everyone.", options: ["should follow", "should be followed", "follow", "are followed"], answer: 1, solution: "1. Aturan adalah yang DIIKUTI, jadi pasif. 2. Modal passive: should be + past participle. 3. Jadi jawabannya should be followed." },
    { q: "The paintings ___ from the museum last night.", options: ["have stolen", "stole", "were stolen", "are stolen"], answer: 2, solution: "1. Lukisan adalah yang DICURI, jadi pasif. 2. Last night lampau dan subjek jamak: were + past participle. 3. Jadi jawabannya were stolen." },
    { q: "The email ___ just now.", options: ["is just sent", "was just sent", "just sent", "has just been sent"], answer: 3, solution: "1. Email adalah yang DIKIRIM, jadi pasif. 2. Just now dengan hasil relevan kini: present perfect passive has been + past participle. 3. Jadi jawabannya has just been sent." },
    { q: "A new hospital ___ near the river at the moment.", options: ["is being built", "builds", "was built", "is built"], answer: 0, solution: "1. Rumah sakit adalah yang DIBANGUN, jadi pasif. 2. At the moment sedang berlangsung: is being + past participle. 3. Jadi jawabannya is being built." },
    { q: "The decision ___ after long deliberation.", options: ["made", "was made", "is made", "has made"], answer: 1, solution: "1. Keputusan adalah yang DIBUAT, jadi pasif. 2. Konteks lampau: was + past participle. 3. Jadi jawabannya was made." },
    { q: "The trees ___ when the rain began.", options: ["planted", "were planted", "were being planted", "are planted"], answer: 2, solution: "1. Pohon adalah yang DITANAM, jadi pasif. 2. Sedang berlangsung saat hujan mulai: past continuous passive were being + past participle. 3. Jadi jawabannya were being planted." },
    { q: "The contract ___ by Monday.", options: ["will be signed", "has signed", "will sign", "will have been signed"], answer: 3, solution: "1. Kontrak adalah yang DITANDATANGANI, jadi pasif. 2. By Monday menandakan selesai sebelum waktu di masa depan: future perfect passive will have been + past participle. 3. Jadi jawabannya will have been signed." },
    { q: "The suspect ___ to be hiding abroad.", options: ["is believed", "believed", "has believed", "believes"], answer: 0, solution: "1. Pola passive reporting: it is believed that menjadi subject + is believed + to infinitive. 2. Tersangka adalah yang DIYAKINI, jadi pasif. 3. Jadi jawabannya is believed." },
    { q: "The president ___ to be seriously ill.", options: ["says", "is said", "said", "has said"], answer: 1, solution: "1. Pola yang sama: subject + is said + to infinitive untuk kabar tidak langsung. 2. Presiden adalah yang DIKABARKAN, jadi pasif. 3. Jadi jawabannya is said." },
    { q: "The cake ___ by my sister right now.", options: ["was baked", "is baked", "is being baked", "bakes"], answer: 2, solution: "1. Kue adalah yang DIPANGGANG, jadi pasif. 2. Right now sedang berlangsung: is being + past participle. 3. Jadi jawabannya is being baked." },
    { q: "The data ___ carefully by the researchers.", options: ["are analyzed", "have analyzed", "analyzed", "were analyzed"], answer: 3, solution: "1. Data adalah yang DIANALISIS, jadi pasif. 2. Data dianggap jamak dan konteks lampau: were + past participle. 3. Jadi jawabannya were analyzed." },
    { q: "The tickets ___ online.", options: ["can be purchased", "purchase", "are purchased", "can purchase"], answer: 0, solution: "1. Tiket adalah yang DIBELI, jadi pasif. 2. Modal passive: can be + past participle. 3. Jadi jawabannya can be purchased." },
    { q: "If she studies hard, she ___ the exam.", options: ["would pass", "will pass", "passed", "would have passed"], answer: 1, solution: "1. Ini conditional type 1: kondisi nyata di masa depan. 2. Polanya: If + present, will + verb. 3. Jadi jawabannya will pass." },
    { q: "If I had more time, I ___ a new language.", options: ["learn", "will learn", "would learn", "would have learned"], answer: 2, solution: "1. Ini conditional type 2: pengandaian tidak nyata saat ini. 2. Polanya: If + past, would + verb. 3. Jadi jawabannya would learn." },
    { q: "If they had left earlier, they ___ the flight.", options: ["will not miss", "did not miss", "would not miss", "would not have missed"], answer: 3, solution: "1. Ini conditional type 3: penyesalan masa lalu. 2. Polanya: If + past perfect, would have + past participle. 3. Jadi jawabannya would not have missed." },
    { q: "If I had studied medicine, I ___ a doctor now.", options: ["would be", "will be", "am", "would have been"], answer: 0, solution: "1. Ini mixed conditional: syarat di masa lalu, hasil di masa kini. 2. Polanya: If + past perfect, would + verb (present). 3. Jadi jawabannya would be." },
    { q: "If she were more careful, she ___ the vase.", options: ["would not break", "would not have broken", "will not break", "did not break"], answer: 1, solution: "1. Ini mixed conditional: syarat saat ini (were), hasil di masa lalu. 2. Polanya: If + past (present unreal), would have + past participle. 3. Jadi jawabannya would not have broken." },
    { q: "Unless you hurry, you ___ late.", options: ["are", "were", "will be", "would be"], answer: 2, solution: "1. Unless artinya if not, kalimat ini type 1. 2. Polanya: If + present, will + verb. 3. Jadi jawabannya will be." },
    { q: "If he had driven carefully, the accident ___.", options: ["will not happen", "did not happen", "would not happen", "would not have happened"], answer: 3, solution: "1. Ini conditional type 3 tentang masa lalu. 2. Polanya: would have + past participle. 3. Jadi jawabannya would not have happened." },
    { q: "Were I you, I ___ immediately.", options: ["would apologize", "will apologize", "apologized", "apologize"], answer: 0, solution: "1. Were I you adalah inversi dari If I were you (type 2). 2. Klausa hasil type 2 memakai would + verb. 3. Jadi jawabannya would apologize." },
    { q: "Had she known the truth, she ___ differently.", options: ["would act", "would have acted", "will act", "acted"], answer: 1, solution: "1. Had she known adalah inversi dari If she had known (type 3). 2. Klausa hasil type 3 memakai would have + past participle. 3. Jadi jawabannya would have acted." },
    { q: "Should you need help, ___ me.", options: ["would call", "calls", "call", "called"], answer: 2, solution: "1. Should you need adalah inversi dari If you should need (type 1). 2. Ini kalimat perintah, jadi pakai verb dasar. 3. Jadi jawabannya call." },
    { q: "If I see him tomorrow, I ___ him the news.", options: ["would tell", "told", "would have told", "will tell"], answer: 3, solution: "1. Ini conditional type 1 dengan tomorrow. 2. Polanya: If + present, will + verb. 3. Jadi jawabannya will tell." },
    { q: "If it had not rained, we ___ hiking.", options: ["would have gone", "will go", "went", "would go"], answer: 0, solution: "1. Ini conditional type 3: penyesalan masa lalu. 2. Polanya: would have + past participle. 3. Jadi jawabannya would have gone." },
    { q: "If you heat water to 100 degrees Celsius, it ___.", options: ["boiled", "boils", "will boil", "would boil"], answer: 1, solution: "1. Ini zero conditional: kebenaran umum atau fakta ilmiah. 2. Polanya: If + present, present. 3. Jadi jawabannya boils." },
    { q: "If I were taller, I ___ the top shelf.", options: ["reach", "can reach", "could reach", "will reach"], answer: 2, solution: "1. Ini conditional type 2: pengandaian saat ini. 2. Can dalam klausa hasil menjadi could. 3. Jadi jawabannya could reach." },
    { q: "She ___ if she had not given up.", options: ["will succeed", "succeeded", "would succeed", "would have succeeded"], answer: 3, solution: "1. Syaratnya past perfect (had not given up), jadi type 3. 2. Polanya: would have + past participle. 3. Jadi jawabannya would have succeeded." },
    { q: "If you had told me, I ___ you.", options: ["would have helped", "will help", "helped", "would help"], answer: 0, solution: "1. Syaratnya past perfect, jadi conditional type 3. 2. Polanya: would have + past participle. 3. Jadi jawabannya would have helped." },
    { q: "If they invite me, I ___.", options: ["came", "will come", "would come", "would have come"], answer: 1, solution: "1. Ini conditional type 1: kemungkinan nyata. 2. Polanya: If + present, will + verb. 3. Jadi jawabannya will come." },
    { q: "Had I been there, I ___ them.", options: ["stopped", "would stop", "would have stopped", "will stop"], answer: 2, solution: "1. Had I been adalah inversi type 3 (If I had been). 2. Hasilnya: would have + past participle. 3. Jadi jawabannya would have stopped." },
    { q: "If he were not so busy, he ___ us.", options: ["would have joined", "joins", "will join", "would join"], answer: 3, solution: "1. Were not so busy adalah pengandaian saat ini (type 2). 2. Polanya: would + verb. 3. Jadi jawabannya would join." },
    { q: "If you mix red and blue, you ___ purple.", options: ["get", "will get", "would get", "got"], answer: 0, solution: "1. Ini zero conditional: fakta umum yang selalu benar. 2. Kedua klausa memakai present tense. 3. Jadi jawabannya get." },
    { q: "She ___ you if she finishes early.", options: ["called", "will call", "would call", "would have called"], answer: 1, solution: "1. Ini conditional type 1. 2. Polanya: will + verb di klausa utama. 3. Jadi jawabannya will call." },
    { q: "If I had known you were coming, I ___ dinner.", options: ["prepared", "would prepare", "would have prepared", "will prepare"], answer: 2, solution: "1. Syaratnya past perfect (had known), jadi type 3. 2. Polanya: would have + past participle. 3. Jadi jawabannya would have prepared." },
    { q: "Unless it rains, the match ___.", options: ["would continue", "continues", "continued", "will continue"], answer: 3, solution: "1. Unless sama dengan if not, kalimat ini type 1. 2. Polanya: will + verb. 3. Jadi jawabannya will continue." },
    { q: "If he had been more patient, he ___ successful now.", options: ["would be", "will be", "is", "would have been"], answer: 0, solution: "1. Ini mixed conditional: syarat masa lalu (had been), hasil masa kini (now). 2. Polanya: would + verb untuk hasil kini. 3. Jadi jawabannya would be." },
    { q: "Were she here, she ___ what to do.", options: ["knows", "would know", "will know", "would have known"], answer: 1, solution: "1. Were she here adalah inversi type 2. 2. Hasil type 2 memakai would + verb. 3. Jadi jawabannya would know." },
    { q: "The committee recommended that the proposal ___ revised.", options: ["will be", "is", "be", "was"], answer: 2, solution: "1. Recommend termasuk kata subjunctive. 2. Polanya: recommend that + subject + bare infinitive. 3. Jadi jawabannya be." },
    { q: "It is essential that every student ___ the instructions.", options: ["followed", "following", "follows", "follow"], answer: 3, solution: "1. Pola it is essential that termasuk subjunctive. 2. Setelah that dipakai bare infinitive untuk semua subjek. 3. Jadi jawabannya follow." },
    { q: "The doctor insisted that he ___ in bed.", options: ["stay", "stayed", "staying", "stays"], answer: 0, solution: "1. Insist termasuk kata subjunctive. 2. Polanya: insist that + subject + bare infinitive. 3. Jadi jawabannya stay." },
    { q: "She demanded that the report ___ submitted immediately.", options: ["is", "be", "was", "will be"], answer: 1, solution: "1. Demand termasuk kata subjunctive. 2. Dipakai bare infinitive tanpa s walau subjeknya tunggal. 3. Jadi jawabannya be." },
    { q: "It is vital that he ___ present at the meeting.", options: ["will be", "is", "be", "was"], answer: 2, solution: "1. Pola it is vital that termasuk subjunctive. 2. Setelah that dipakai bentuk dasar be. 3. Jadi jawabannya be." },
    { q: "The judge ordered that the defendant ___ silent.", options: ["remained", "remaining", "remains", "remain"], answer: 3, solution: "1. Order termasuk kata subjunctive. 2. Polanya: order that + subject + bare infinitive. 3. Jadi jawabannya remain." },
    { q: "They requested that she ___ the committee.", options: ["join", "joined", "joining", "joins"], answer: 0, solution: "1. Request termasuk kata subjunctive. 2. Bentuk dasar dipakai untuk semua subjek, tanpa s. 3. Jadi jawabannya join." },
    { q: "It is necessary that the data ___ verified.", options: ["is", "be", "was", "are"], answer: 1, solution: "1. Pola it is necessary that termasuk subjunctive. 2. Setelah that dipakai bare infinitive be. 3. Jadi jawabannya be." },
    { q: "He suggested that we ___ earlier.", options: ["leaving", "leaves", "leave", "left"], answer: 2, solution: "1. Suggest termasuk kata subjunctive. 2. Polanya: suggest that + subject + bare infinitive. 3. Jadi jawabannya leave." },
    { q: "The manager proposed that the budget ___ increased.", options: ["was", "will be", "is", "be"], answer: 3, solution: "1. Propose termasuk kata subjunctive. 2. Dipakai bare infinitive untuk semua subjek. 3. Jadi jawabannya be." },
    { q: "It is crucial that she ___ her passport.", options: ["bring", "brought", "bringing", "brings"], answer: 0, solution: "1. Pola it is crucial that termasuk subjunctive. 2. Bentuk dasar tanpa s dipakai walau subjeknya she. 3. Jadi jawabannya bring." },
    { q: "The teacher required that each student ___ a draft.", options: ["submits", "submit", "submitted", "submitting"], answer: 1, solution: "1. Require termasuk kata subjunctive. 2. Polanya: require that + subject + bare infinitive. 3. Jadi jawabannya submit." },
    { q: "I recommend that he ___ a lawyer.", options: ["consulting", "consults", "consult", "consulted"], answer: 2, solution: "1. Recommend termasuk kata subjunctive. 2. Dipakai bentuk dasar tanpa s. 3. Jadi jawabannya consult." },
    { q: "It was imperative that they ___ on time.", options: ["arrives", "arrived", "arriving", "arrive"], answer: 3, solution: "1. Pola it was imperative that termasuk subjunctive. 2. Setelah that dipakai bare infinitive. 3. Jadi jawabannya arrive." },
    { q: "The law requires that every citizen ___ taxes.", options: ["pay", "paid", "paying", "pays"], answer: 0, solution: "1. Require termasuk kata subjunctive. 2. Bentuk dasar dipakai untuk semua subjek. 3. Jadi jawabannya pay." },
    { q: "She avoided ___ about the incident.", options: ["to talk", "talking", "talk", "talked"], answer: 1, solution: "1. Avoid termasuk verb yang diikuti gerund. 2. Avoid tidak bisa diikuti to-infinitive. 3. Jadi jawabannya talking." },
    { q: "He promised ___ me after the meeting.", options: ["call", "called", "to call", "calling"], answer: 2, solution: "1. Promise termasuk verb yang diikuti to-infinitive. 2. Janji untuk aksi di masa depan memakai to + verb. 3. Jadi jawabannya to call." },
    { q: "They enjoy ___ novels in their free time.", options: ["read", "reads", "to read", "reading"], answer: 3, solution: "1. Enjoy termasuk verb yang diikuti gerund. 2. Enjoy tidak bisa diikuti to-infinitive. 3. Jadi jawabannya reading." },
    { q: "I decided ___ a new course this semester.", options: ["to take", "taking", "take", "taken"], answer: 0, solution: "1. Decide termasuk verb yang diikuti to-infinitive. 2. Keputusan memakai to + verb dasar. 3. Jadi jawabannya to take." },
    { q: "She finished ___ her thesis last month.", options: ["to write", "writing", "write", "written"], answer: 1, solution: "1. Finish termasuk verb yang diikuti gerund. 2. Menyelesaikan suatu aktivitas memakai verb-ing. 3. Jadi jawabannya writing." },
    { q: "He refused ___ the document.", options: ["sign", "signed", "to sign", "signing"], answer: 2, solution: "1. Refuse termasuk verb yang diikuti to-infinitive. 2. Penolakan memakai to + verb dasar. 3. Jadi jawabannya to sign." },
    { q: "We discussed ___ to the mountains.", options: ["go", "gone", "to go", "going"], answer: 3, solution: "1. Discuss termasuk verb yang diikuti gerund. 2. Discuss tidak bisa diikuti to-infinitive. 3. Jadi jawabannya going." },
    { q: "She hopes ___ a scholarship next year.", options: ["to get", "getting", "get", "got"], answer: 0, solution: "1. Hope termasuk verb yang diikuti to-infinitive. 2. Harapan untuk masa depan memakai to + verb. 3. Jadi jawabannya to get." },
    { q: "He admitted ___ the window.", options: ["to break", "breaking", "break", "broken"], answer: 1, solution: "1. Admit termasuk verb yang diikuti gerund. 2. Mengakui perbuatan lampau memakai verb-ing. 3. Jadi jawabannya breaking." },
    { q: "They agreed ___ the cost equally.", options: ["share", "shared", "to share", "sharing"], answer: 2, solution: "1. Agree termasuk verb yang diikuti to-infinitive. 2. Kesepakatan memakai to + verb dasar. 3. Jadi jawabannya to share." },
    { q: "I miss ___ football with my old friends.", options: ["play", "played", "to play", "playing"], answer: 3, solution: "1. Miss (merindukan) termasuk verb yang diikuti gerund. 2. Merindukan aktivitas memakai verb-ing. 3. Jadi jawabannya playing." },
    { q: "She learned ___ a bicycle when she was five.", options: ["to ride", "riding", "ride", "ridden"], answer: 0, solution: "1. Learn termasuk verb yang diikuti to-infinitive. 2. Mempelajari keterampilan memakai to + verb. 3. Jadi jawabannya to ride." },
    { q: "He kept ___ during the lecture.", options: ["to talk", "talking", "talk", "talked"], answer: 1, solution: "1. Keep (terus-menerus) termasuk verb yang diikuti gerund. 2. Melanjutkan aktivitas memakai verb-ing. 3. Jadi jawabannya talking." },
    { q: "We plan ___ the new library next week.", options: ["visit", "visited", "to visit", "visiting"], answer: 2, solution: "1. Plan termasuk verb yang diikuti to-infinitive. 2. Rencana memakai to + verb dasar. 3. Jadi jawabannya to visit." },
    { q: "She considered ___ abroad.", options: ["study", "studied", "to study", "studying"], answer: 3, solution: "1. Consider termasuk verb yang diikuti gerund. 2. Mempertimbangkan memakai verb-ing. 3. Jadi jawabannya studying." },
    { q: "He offered ___ me with my luggage.", options: ["to help", "helping", "help", "helped"], answer: 0, solution: "1. Offer termasuk verb yang diikuti to-infinitive. 2. Tawaran memakai to + verb dasar. 3. Jadi jawabannya to help." },
    { q: "I remember ___ the door before I left.", options: ["to lock", "locking", "lock", "locked"], answer: 1, solution: "1. Remember + gerund artinya mengingat kejadian lampau. 2. Mengunci pintu sudah terjadi sebelum pergi. 3. Jadi jawabannya locking." },
    { q: "Remember ___ the lights before you leave.", options: ["turn off", "turned off", "to turn off", "turning off"], answer: 2, solution: "1. Remember + to-infinitive artinya jangan lupa melakukan sesuatu. 2. Mematikan lampu belum dilakukan, jadi pakai to-infinitive. 3. Jadi jawabannya to turn off." },
    { q: "She stopped ___ when the teacher entered.", options: ["talk", "talked", "to talk", "talking"], answer: 3, solution: "1. Stop + gerund artinya berhenti melakukan aktivitas. 2. Dia berhenti berbicara saat guru masuk. 3. Jadi jawabannya talking." },
    { q: "He stopped ___ some coffee on the way home.", options: ["to buy", "buying", "buy", "bought"], answer: 0, solution: "1. Stop + to-infinitive artinya berhenti sejenak untuk melakukan hal lain. 2. Dia berhenti dalam perjalanan untuk membeli kopi. 3. Jadi jawabannya to buy." },
    { q: "They threatened ___ the workers.", options: ["dismissed", "to dismiss", "dismissing", "dismiss"], answer: 1, solution: "1. Threaten termasuk verb yang diikuti to-infinitive. 2. Ancaman memakai to + verb dasar. 3. Jadi jawabannya to dismiss." },
    { q: "I regret ___ you that the trip was cancelled.", options: ["inform", "informed", "to inform", "informing"], answer: 2, solution: "1. Regret + to-infinitive dipakai saat menyampaikan kabar buruk. 2. Pemberitahuan terjadi saat berbicara, bukan lampau. 3. Jadi jawabannya to inform." },
    { q: "He regrets ___ so much money.", options: ["spend", "spent", "to spend", "spending"], answer: 3, solution: "1. Regret + gerund artinya menyesali perbuatan lampau. 2. Uang sudah dihabiskan, jadi pakai verb-ing. 3. Jadi jawabannya spending." },
    { q: "She tried ___ the door, but it was locked.", options: ["to open", "opening", "open", "opened"], answer: 0, solution: "1. Try + to-infinitive artinya berusaha melakukan sesuatu. 2. Dia berusaha membuka pintu tetapi gagal. 3. Jadi jawabannya to open." },
    { q: "He tried ___ yoga to reduce stress.", options: ["to do", "doing", "do", "done"], answer: 1, solution: "1. Try + gerund artinya mencoba suatu aktivitas sebagai eksperimen. 2. Dia mencoba yoga untuk melihat efeknya. 3. Jadi jawabannya doing." },
    { q: "Never ___ such a beautiful sunset.", options: ["do I see", "I have seen", "have I seen", "I saw"], answer: 2, solution: "1. Never di awal kalimat memicu inversi. 2. Present perfect: have + subjek + past participle menjadi have I seen. 3. Jadi jawabannya have I seen." },
    { q: "Rarely ___ so much rain in April.", options: ["we got", "have we got", "we get", "do we get"], answer: 3, solution: "1. Rarely di awal kalimat memicu inversi. 2. Present tense: do + subjek + verb dasar menjadi do we get. 3. Jadi jawabannya do we get." },
    { q: "Not until midnight ___ home.", options: ["did he come", "he comes", "does he come", "he came"], answer: 0, solution: "1. Not until di awal kalimat memicu inversi. 2. Kejadiannya lampau: did + subjek + verb dasar. 3. Jadi jawabannya did he come." },
    { q: "Seldom ___ to the cinema these days.", options: ["I go", "do I go", "I went", "have I gone"], answer: 1, solution: "1. Seldom di awal kalimat memicu inversi. 2. These days menandakan present: do + subjek + verb dasar. 3. Jadi jawabannya do I go." },
    { q: "Little ___ about the surprise party.", options: ["does she know", "she knew", "did she know", "she knows"], answer: 2, solution: "1. Little (hampir tidak) di awal kalimat memicu inversi. 2. Kejadiannya lampau: did + subjek + verb dasar. 3. Jadi jawabannya did she know." },
    { q: "Only after the meeting ___ the truth.", options: ["we learn", "do we learn", "we learned", "did we learn"], answer: 3, solution: "1. Only after di awal kalimat memicu inversi. 2. Kejadiannya lampau: did + subjek + verb dasar. 3. Jadi jawabannya did we learn." },
    { q: "No sooner had he arrived ___ the meeting started.", options: ["than", "then", "that", "when"], answer: 0, solution: "1. Pasangan tetap dari no sooner adalah than. 2. When adalah pasangan hardly/scarcely, bukan no sooner. 3. Jadi jawabannya than." },
    { q: "Never before ___ such courage.", options: ["we had witnessed", "had we witnessed", "we witnessed", "do we witness"], answer: 1, solution: "1. Never before di awal kalimat memicu inversi. 2. Past perfect: had + subjek + past participle. 3. Jadi jawabannya had we witnessed." },
    { q: "Barely had she sat down ___ the phone rang.", options: ["that", "than", "when", "then"], answer: 2, solution: "1. Pasangan tetap dari barely/hardly/scarcely adalah when. 2. Than hanya pasangan no sooner. 3. Jadi jawabannya when." },
    { q: "Not only did she win, but she ___ a new record.", options: ["set also", "did also set", "also did set", "also set"], answer: 3, solution: "1. Setelah not only + inversi, klausa kedua memakai but + subjek + also + verb. 2. Inversi hanya terjadi di klausa pertama. 3. Jadi jawabannya also set." },
    { q: "Under no circumstances ___ leave the building.", options: ["must you", "you will", "do you", "you must"], answer: 0, solution: "1. Frasa negatif under no circumstances di awal memicu inversi. 2. Modal must pindah ke depan subjek: must you. 3. Jadi jawabannya must you." },
    { q: "Hardly had the show begun ___ the lights went out.", options: ["than", "when", "then", "that"], answer: 1, solution: "1. Pasangan tetap dari hardly adalah when. 2. Pola hardly had ... when ... untuk dua kejadian berurutan. 3. Jadi jawabannya when." },
    { q: "So tired ___ that she fell asleep.", options: ["she is", "she was", "was she", "is she"], answer: 2, solution: "1. So + adjective di awal kalimat memicu inversi. 2. To be pindah ke depan subjek: was she. 3. Jadi jawabannya was she." },
    { q: "On no account ___ open this door.", options: ["you should", "do you", "you must", "must you"], answer: 3, solution: "1. On no account di awal kalimat memicu inversi. 2. Modal must pindah ke depan subjek. 3. Jadi jawabannya must you." },
    { q: "Only by working hard ___ succeed.", options: ["can you", "you will", "do you", "you can"], answer: 0, solution: "1. Only by + gerund di awal kalimat memicu inversi. 2. Modal can pindah ke depan subjek: can you. 3. Jadi jawabannya can you." },
    { q: "The word MITIGATE is closest in meaning to ...", options: ["worsen", "make less severe", "ignore", "accelerate"], answer: 1, solution: "1. Mitigate berasal dari kata Latin mitigare yang berarti melunakkan. 2. Artinya membuat sesuatu yang buruk menjadi tidak terlalu parah. 3. Jadi jawabannya make less severe." },
    { q: "The word EMPIRICAL is closest in meaning to ...", options: ["emotional", "theoretical", "based on observation or experiment", "imaginary"], answer: 2, solution: "1. Empirical berasal dari kata Yunani empeiria yang berarti pengalaman. 2. Artinya berdasarkan pengamatan atau percobaan nyata. 3. Jadi jawabannya based on observation or experiment." },
    { q: "The word PREVALENT is closest in meaning to ...", options: ["hidden", "temporary", "rare", "widespread in a certain area"], answer: 3, solution: "1. Prevalent menggambarkan sesuatu yang umum terjadi. 2. Artinya tersebar luas di suatu wilayah atau kelompok. 3. Jadi jawabannya widespread in a certain area." },
    { q: "The word FEASIBLE is closest in meaning to ...", options: ["possible and practical to achieve", "expensive", "illegal", "impossible"], answer: 0, solution: "1. Feasible berasal dari kata Latin facere yang berarti melakukan. 2. Artinya mungkin dan praktis untuk dilaksanakan. 3. Jadi jawabannya possible and practical to achieve." },
    { q: "The word COHERENT is closest in meaning to ...", options: ["confusing", "logical and consistent", "loud", "brief"], answer: 1, solution: "1. Coherent berasal dari co (bersama) + haerere (melekat). 2. Artinya logis, runtut, dan saling terhubung. 3. Jadi jawabannya logical and consistent." },
    { q: "The word PROFOUND is closest in meaning to ...", options: ["simple", "shallow", "very great or intense", "short"], answer: 2, solution: "1. Profound menggambarkan kedalaman, baik harfiah maupun kiasan. 2. Artinya sangat besar atau sangat dalam pengaruhnya. 3. Jadi jawabannya very great or intense." },
    { q: "The word PLAUSIBLE is closest in meaning to ...", options: ["proven false", "boring", "unlikely", "seeming reasonable or probably true"], answer: 3, solution: "1. Plausible berasal dari kata Latin plaudere yang berarti bertepuk tangan tanda setuju. 2. Artinya tampak masuk akal atau mungkin benar. 3. Jadi jawabannya seeming reasonable or probably true." },
    { q: "The word ARBITRARY is closest in meaning to ...", options: ["based on random choice rather than reason", "careful", "legal", "logical"], answer: 0, solution: "1. Arbitrary berasal dari arbiter (penengah yang memutuskan sendiri). 2. Artinya berdasarkan pilihan acak, bukan alasan jelas. 3. Jadi jawabannya based on random choice rather than reason." },
    { q: "The word ALLEVIATE is closest in meaning to ...", options: ["increase", "make suffering less severe", "ignore", "cause"], answer: 1, solution: "1. Alleviate berasal dari kata Latin alleviare yang berarti meringankan. 2. Artinya mengurangi penderitaan atau masalah. 3. Jadi jawabannya make suffering less severe." },
    { q: "The word SCRUTINY is closest in meaning to ...", options: ["speed", "praise", "critical examination", "neglect"], answer: 2, solution: "1. Scrutiny menggambarkan pemeriksaan yang sangat teliti. 2. Artinya pengamatan atau pemeriksaan kritis. 3. Jadi jawabannya critical examination." },
    { q: "The word CREDIBLE is closest in meaning to ...", options: ["famous", "rich", "doubtful", "able to be believed"], answer: 3, solution: "1. Credible berasal dari kata Latin credere yang berarti percaya. 2. Artinya dapat dipercaya atau meyakinkan. 3. Jadi jawabannya able to be believed." },
    { q: "The word OBSOLETE is closest in meaning to ...", options: ["no longer used", "popular", "new", "modern"], answer: 0, solution: "1. Obsolete menggambarkan sesuatu yang ditinggalkan zaman. 2. Artinya sudah tidak dipakai lagi. 3. Jadi jawabannya no longer used." },
    { q: "The word RESILIENT is closest in meaning to ...", options: ["fragile", "able to recover quickly", "rigid", "weak"], answer: 1, solution: "1. Resilient berasal dari kata Latin resilire yang berarti melompat kembali. 2. Artinya mampu pulih dengan cepat dari kesulitan. 3. Jadi jawabannya able to recover quickly." },
    { q: "The word RIGOROUS is closest in meaning to ...", options: ["easy", "careless", "extremely thorough and careful", "quick"], answer: 2, solution: "1. Rigorous menggambarkan standar yang sangat ketat. 2. Artinya sangat teliti dan menyeluruh. 3. Jadi jawabannya extremely thorough and careful." },
    { q: "The word SKEPTICAL is closest in meaning to ...", options: ["excited", "certain", "trusting", "doubting the truth of something"], answer: 3, solution: "1. Skeptical berasal dari kata Yunani skeptikos yang berarti mempertanyakan. 2. Artinya meragukan kebenaran sesuatu. 3. Jadi jawabannya doubting the truth of something." },
    { q: "The word UNPRECEDENTED is closest in meaning to ...", options: ["never done or known before", "old", "expected", "common"], answer: 0, solution: "1. Unprecedented berasal dari un (tidak) + precedent (contoh sebelumnya). 2. Artinya belum pernah terjadi sebelumnya. 3. Jadi jawabannya never done or known before." },
    { q: "The word VERSATILE is closest in meaning to ...", options: ["limited", "able to be used for many purposes", "fragile", "single-purpose"], answer: 1, solution: "1. Versatile berasal dari kata Latin versatilis yang berarti mudah diputar. 2. Artinya bisa dipakai untuk banyak keperluan. 3. Jadi jawabannya able to be used for many purposes." },
    { q: "The word PARADOX is closest in meaning to ...", options: ["question", "simple fact", "a seemingly contradictory statement that may be true", "lie"], answer: 2, solution: "1. Paradox berasal dari kata Yunani paradoxon yang berarti bertentangan dengan pendapat umum. 2. Artinya pernyataan yang tampak bertentangan tapi mungkin benar. 3. Jadi jawabannya a seemingly contradictory statement that may be true." },
    { q: "The word HYPOTHESIS is closest in meaning to ...", options: ["conclusion", "baseless guess", "proven fact", "a proposed explanation to be tested"], answer: 3, solution: "1. Hypothesis berasal dari kata Yunani hypothesis yang berarti dasar pemikiran. 2. Artinya dugaan penjelasan yang harus diuji. 3. Jadi jawabannya a proposed explanation to be tested." },
    { q: "The word PHENOMENON is closest in meaning to ...", options: ["an observable fact or event", "theory", "dream", "invisible thing"], answer: 0, solution: "1. Phenomenon berasal dari kata Yunani phainomenon yang berarti yang tampak. 2. Artinya fakta atau peristiwa yang dapat diamati. 3. Jadi jawabannya an observable fact or event." },
    { q: "The word DILIGENT is closest in meaning to ...", options: ["lazy", "showing care and hard work", "careless", "slow"], answer: 1, solution: "1. Diligent menggambarkan orang yang rajin dan teliti. 2. Artinya tekun dan sungguh-sungguh dalam bekerja. 3. Jadi jawabannya showing care and hard work." },
    { q: "The word APPREHENSIVE is closest in meaning to ...", options: ["brave", "calm", "anxious or fearful about the future", "confident"], answer: 2, solution: "1. Apprehensive menggambarkan perasaan khawatir. 2. Artinya cemas atau takut tentang apa yang akan terjadi. 3. Jadi jawabannya anxious or fearful about the future." },
    { q: "The word SUBSTANTIATE is closest in meaning to ...", options: ["ignore", "weaken", "deny", "provide evidence to support a claim"], answer: 3, solution: "1. Substantiate berasal dari substance (bahan bukti). 2. Artinya memberikan bukti untuk mendukung klaim. 3. Jadi jawabannya provide evidence to support a claim." },
    { q: "The word CORRELATION is closest in meaning to ...", options: ["a mutual relationship between two things", "cause", "coincidence", "difference"], answer: 0, solution: "1. Correlation berasal dari co (bersama) + relation (hubungan). 2. Artinya hubungan timbal balik antara dua hal. 3. Jadi jawabannya a mutual relationship between two things." },
    { q: "The word AESTHETIC is closest in meaning to ...", options: ["ugly", "concerned with beauty", "practical", "moral"], answer: 1, solution: "1. Aesthetic berasal dari kata Yunani aisthetikos yang berkaitan dengan indra. 2. Artinya berkaitan dengan keindahan. 3. Jadi jawabannya concerned with beauty." },
    { q: "Read the passage: Deforestation destroys the habitats of countless species and releases stored carbon into the atmosphere, accelerating climate change. What is the main idea of the passage?", options: ["Carbon is harmless to the atmosphere", "Deforestation only affects local weather", "Deforestation harms wildlife and worsens climate change", "Trees grow back quickly after logging"], answer: 2, solution: "1. Kalimat menyebut dua akibat: habitat hancur dan karbon dilepas. 2. Keduanya adalah dampak negatif deforestasi. 3. Ide pokoknya: deforestation harms wildlife and worsens climate change." },
    { q: "Read the passage: Despite advances in medicine, antibiotic resistance is rising because patients often stop taking prescriptions too early. It can be inferred that ...", options: ["antibiotics are no longer manufactured", "doctors never prescribe antibiotics", "resistance only affects animals", "new drugs alone cannot solve antibiotic resistance"], answer: 3, solution: "1. Teks menyebut resistensi meningkat karena pasien berhenti minum obat terlalu dini. 2. Artinya masalahnya ada pada perilaku, bukan sekadar kurangnya obat baru. 3. Kesimpulannya: new drugs alone cannot solve antibiotic resistance." },
    { q: "Read the passage: Rapid urbanization has created crowded cities with heavy traffic, yet it has also brought better hospitals, schools, and job opportunities. What is the main idea of the passage?", options: ["Urbanization brings both problems and benefits", "Traffic is the only problem of cities", "Villages are better than cities", "Cities are always unpleasant places"], answer: 0, solution: "1. Kata yet menandakan dua sisi: masalah (macet, padat) dan manfaat (rumah sakit, sekolah, pekerjaan). 2. Teks menyeimbangkan sisi negatif dan positif. 3. Ide pokoknya: urbanization brings both problems and benefits." },
    { q: "Read the passage: Honeybees communicate the location of flowers through intricate dances, with the angle and duration indicating direction and distance. What is the main idea of the passage?", options: ["Bees are dangerous insects", "Bees communicate flower locations through dances", "Flowers attract bees with bright colors", "Bees live in large colonies"], answer: 1, solution: "1. Kalimat pertama langsung menjelaskan cara lebah berkomunikasi. 2. Detail sudut dan durasi mendukung ide tersebut. 3. Ide pokoknya: bees communicate flower locations through dances." },
    { q: "Read the passage: Solar and wind power are now cheaper than coal in many regions, and battery technology keeps improving. It can be inferred that ...", options: ["renewable energy cannot be stored", "solar power works only at night", "fossil fuels will become less dominant in energy production", "coal will remain the cheapest energy forever"], answer: 2, solution: "1. Teks menyebut energi terbarukan lebih murah dan baterai makin baik. 2. Dua keunggulan ini melemahkan posisi bahan bakar fosil. 3. Kesimpulannya: fossil fuels will become less dominant in energy production." },
    { q: "Read the passage: Sleep deprivation impairs memory, weakens the immune system, and increases the risk of accidents. What is the main idea of the passage?", options: ["Accidents happen only at night", "Memory improves without sleep", "Sleep is unnecessary for adults", "Lack of sleep harms health and safety"], answer: 3, solution: "1. Teks mendaftar tiga dampak negatif kurang tidur. 2. Semuanya berkaitan dengan kesehatan dan keselamatan. 3. Ide pokoknya: lack of sleep harms health and safety." },
    { q: "Read the passage: The Great Wall of China stretches over 21,000 kilometers and was built over many dynasties to protect against invasions. Which statement is TRUE according to the passage?", options: ["The Great Wall is over 21,000 kilometers long", "The Great Wall was built in a single year", "The Great Wall was built for tourism", "The Great Wall is located in Japan"], answer: 0, solution: "1. Teks menyebut stretches over 21,000 kilometers. 2. Teks menyebut built over many dynasties, bukan setahun, dan untuk pertahanan. 3. Pernyataan yang benar: the Great Wall is over 21,000 kilometers long." },
    { q: "Read the passage: Volunteering benefits both the community and the volunteers themselves, who often gain new skills and confidence. What is the main idea of the passage?", options: ["Volunteering only helps the poor", "Volunteering benefits both communities and volunteers", "Volunteering is a waste of time", "Only students should volunteer"], answer: 1, solution: "1. Teks menyebut manfaat bagi komunitas dan bagi relawan. 2. Kata both menegaskan dua pihak diuntungkan. 3. Ide pokoknya: volunteering benefits both communities and volunteers." },
    { q: "Read the passage: Microplastics have been found in drinking water, seafood, and even human blood, though their long-term health effects remain unknown. It can be inferred that ...", options: ["humans are immune to microplastics", "microplastics are proven harmless", "more research on microplastics is urgently needed", "microplastics exist only in oceans"], answer: 2, solution: "1. Teks menyebut mikroplastik ada di mana-mana tapi efeknya belum diketahui. 2. Ketidaktahuan tentang bahaya menuntut penelitian lebih lanjut. 3. Kesimpulannya: more research on microplastics is urgently needed." },
    { q: "Read the passage: The city library will close for six months for renovation, during which all book loans must be returned beforehand. It can be inferred that ...", options: ["the library is being demolished", "books will be given away for free", "the library will never reopen", "borrowers cannot access books during the renovation"], answer: 3, solution: "1. Teks menyebut tutup enam bulan untuk renovasi dan buku harus dikembalikan. 2. Artinya selama renovasi tidak ada peminjaman. 3. Kesimpulannya: borrowers cannot access books during the renovation." },
    { q: "Read the passage: Online learning expanded rapidly during the pandemic, giving students flexibility but also revealing gaps in internet access and self-discipline. What is the main idea of the passage?", options: ["Online learning brought flexibility but exposed new challenges", "All students prefer online learning", "The pandemic improved internet access everywhere", "Online learning has only disadvantages"], answer: 0, solution: "1. Teks menyebut manfaat (flexibility) dan masalah (akses internet, disiplin). 2. Kata but menandakan dua sisi. 3. Ide pokoknya: online learning brought flexibility but exposed new challenges." },
    { q: "Read the passage: Coral reefs, often called the rainforests of the sea, support a quarter of all marine species despite covering less than one percent of the ocean floor. What is the main idea of the passage?", options: ["Coral reefs are unimportant ecosystems", "Coral reefs support huge biodiversity in a tiny area", "All marine species live in coral reefs", "The ocean floor is mostly coral reefs"], answer: 1, solution: "1. Teks menekankan seperempat spesies laut didukung terumbu karang. 2. Padahal luasnya kurang dari satu persen dasar laut. 3. Ide pokoknya: coral reefs support huge biodiversity in a tiny area." },
    { q: "Read the passage: Studies show that bilingual children tend to switch between tasks more easily and solve problems more creatively than monolingual children. It can be inferred that ...", options: ["all bilingual children are geniuses", "language learning harms creativity", "bilingualism may strengthen cognitive flexibility", "monolingual children cannot solve problems"], answer: 2, solution: "1. Teks menyebut anak bilingual lebih mudah berpindah tugas dan lebih kreatif. 2. Itu adalah tanda fleksibilitas kognitif yang lebih kuat. 3. Kesimpulannya: bilingualism may strengthen cognitive flexibility." },
    { q: "Read the passage: Electric cars produce no tailpipe emissions, but their environmental benefit depends on how the electricity charging them is generated. It can be inferred that ...", options: ["electric cars need no energy at all", "tailpipe emissions are harmless", "electric cars are always worse than gasoline cars", "clean electricity is needed to maximize their benefit"], answer: 3, solution: "1. Teks menyebut manfaat tergantung pada cara listrik dihasilkan. 2. Artinya listrik kotor mengurangi manfaat mobil listrik. 3. Kesimpulannya: clean electricity is needed to maximize their benefit." },
    { q: "Read the passage: Effective time management begins with prioritizing tasks, setting realistic deadlines, and eliminating distractions. What is the main idea of the passage?", options: ["Time management requires prioritization and focus", "Distractions improve productivity", "Only managers need time management", "Deadlines are unnecessary"], answer: 0, solution: "1. Teks mendaftar tiga langkah: memprioritaskan, tenggat realistis, menghilangkan distraksi. 2. Semuanya tentang fokus dan prioritas. 3. Ide pokoknya: time management requires prioritization and focus." },
    { q: "The word INNOVATION is closest in meaning to ...", options: ["tradition", "a new method or idea", "copy", "failure"], answer: 1, solution: "1. Innovation berasal dari kata Latin innovare yang berarti memperbarui. 2. Artinya metode atau ide baru. 3. Jadi jawabannya a new method or idea." },
    { q: "The word BIAS is closest in meaning to ...", options: ["truth", "fairness", "prejudice in favor of something", "balance"], answer: 2, solution: "1. Bias menggambarkan keberpihakan yang tidak adil. 2. Artinya prasangka yang memihak sesuatu. 3. Jadi jawabannya prejudice in favor of something." },
    { q: "The word CONCISE is closest in meaning to ...", options: ["long", "confusing", "wordy", "giving information clearly in few words"], answer: 3, solution: "1. Concise berasal dari kata Latin concisus yang berarti dipotong pendek. 2. Artinya padat, jelas, dan tidak bertele-tele. 3. Jadi jawabannya giving information clearly in few words." },
    { q: "The word TEDIOUS is closest in meaning to ...", options: ["too long and boring", "short", "fun", "exciting"], answer: 0, solution: "1. Tedious berasal dari kata Latin taedium yang berarti kebosanan. 2. Artinya terlalu panjang dan membosankan. 3. Jadi jawabannya too long and boring." },
    { q: "The word LUCID is closest in meaning to ...", options: ["confusing", "clear and easy to understand", "dark", "complex"], answer: 1, solution: "1. Lucid berasal dari kata Latin lux yang berarti cahaya. 2. Artinya jernih dan mudah dipahami. 3. Jadi jawabannya clear and easy to understand." }
  ]
};
